// Simplified TLB Entry (PTE Cache)
typedef struct {
    unsigned int vpn;       // Virtual Page Number (Key)
    unsigned int pfn;       // Physical Frame Number (Value)
    bool valid;             // Entry is valid
    bool dirty;             // Page has been modified
    unsigned char usage;    // For replacement policies (LRU, etc.)
} TLB_Entry;

#define TLB_SIZE 128
TLB_Entry TLB_CACHE[TLB_SIZE];

// Accelerating Virtual-to-Physical Translation
unsigned int tlb_lookup(unsigned int requested_vpn) {
    for (int i = 0; i < TLB_SIZE; ++i) {
        if (TLB_CACHE[i].valid && TLB_CACHE[i].vpn == requested_vpn) {
            // TLB HIT: Return physical address fast
            return TLB_CACHE[i].pfn;
        }
    }
    // TLB MISS: Must perform slower Page Table Walk
    return 0; // Indicates failure/miss
}
